import type { AssessmentQuestion, CandidateRole } from "@/lib/question-bank";

export type ExpandedRole = Exclude<
  CandidateRole,
  "host_cashier" | "server" | "bartender"
>;

type TechnicalSpec = {
  prompt: string;
  correct: string;
  alternatives: [string, string, string];
  note: string;
};

const s = (
  prompt: string,
  correct: string,
  alternativeOne: string,
  alternativeTwo: string,
  alternativeThree: string,
  note: string,
): TechnicalSpec => ({
  prompt,
  correct,
  alternatives: [alternativeOne, alternativeTwo, alternativeThree],
  note,
});

function makeBank(prefix: string, specs: TechnicalSpec[]): AssessmentQuestion[] {
  if (specs.length !== 45) {
    throw new Error(`${prefix} technical bank must contain exactly 45 questions.`);
  }
  return specs.map((spec, index) => {
    const id = `${prefix}${String(index + 1).padStart(2, "0")}`;
    return {
      id,
      category: "technical",
      prompt: spec.prompt,
      options: [spec.correct, ...spec.alternatives].map((text, optionIndex) => ({
        id: `${id}-${String.fromCharCode(97 + optionIndex)}`,
        text,
        points: optionIndex === 0 ? 3 : 0,
      })),
      reviewNote: spec.note,
    };
  });
}

